1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return no living cells for an empty grid", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should let a single living cell die of underpopulation", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("should let two adjacent living cells die of underpopulation", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 1],
15	        [1, 1],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("should let a living cell with three neighbors survive", () => {
20	    expect(
21	      nextGeneration([
22	        [1, 1],
23	        [0, 0],
24	        [0, 1],
25	        [0, 2],
26	      ]),
27	    ).toContainEqual([1, 1]);
28	  });
29	  it("should let a living cell with four neighbors die of overpopulation", () => {
30	    expect(
31	      nextGeneration([
32	        [1, 1],
33	        [0, 0],
34	        [0, 1],
35	        [0, 2],
36	        [1, 0],
37	      ]),
38	    ).not.toContainEqual([1, 1]);
39	  });
40	  it("should bring a dead cell with exactly three neighbors to life", () => {
41	    expect(
42	      nextGeneration([
43	        [0, 0],
44	        [1, 0],
45	        [0, 1],
46	      ]),
47	    ).toContainEqual([1, 1]);
48	  });
49	  it("should oscillate a vertical blinker into a horizontal blinker", () => {
50	    const result = nextGeneration([
51	      [0, 0],
52	      [0, 1],
53	      [0, 2],
54	    ]);
55	    expect(result).toHaveLength(3);
56	    expect(result).toContainEqual([-1, 1]);
57	    expect(result).toContainEqual([0, 1]);
58	    expect(result).toContainEqual([1, 1]);
59	  });
60	  it("should keep a block unchanged as a still life", () => {
61	    const result = nextGeneration([
62	      [0, 0],
63	      [1, 0],
64	      [0, 1],
65	      [1, 1],
66	    ]);
67	    expect(result).toHaveLength(4);
68	    expect(result).toContainEqual([0, 0]);
69	    expect(result).toContainEqual([1, 0]);
70	    expect(result).toContainEqual([0, 1]);
71	    expect(result).toContainEqual([1, 1]);
72	  });
73	  it("should handle cells at negative coordinates", () => {
74	    const result = nextGeneration([
75	      [-5, -5],
76	      [-5, -4],
77	      [-5, -3],
78	    ]);
79	    expect(result).toHaveLength(3);
80	    expect(result).toContainEqual([-6, -4]);
81	    expect(result).toContainEqual([-5, -4]);
82	    expect(result).toContainEqual([-4, -4]);
83	  });
84	});
